    best_period, best_score = 1, -1.0
    for period in range(1, min(12, max(2, w - 2))):
        matches = total = 0
        for r in range(3, h):
            buckets = [Counter() for _ in range(period)]
            for c in range(3, w):
                value = a[r][c]
